<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") { if (!path || !obj) return defaultValue; let current = obj; const keys = path.split('.'); for (const key of keys) { if (current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) return defaultValue; current = current[key]; } if (current === null || current === undefined) return defaultValue; return Array.isArray(current) && typeof current[0] !== 'object' ? current[0] : current; }
    function setText(id, value, suffix = '') { const el = document.getElementById(id); if (el) el.textContent = value + suffix; }
    function updateProgressBar(barId, valueId, current, max) { const bar = document.getElementById(barId); const valueEl = document.getElementById(valueId); if (valueEl) valueEl.textContent = `${current} / ${max}`; if (bar) { const percentage = max > 0 ? (current / max) * 100 : 0; bar.style.width = `${Math.max(0, Math.min(100, percentage))}%`; } }
    function openPage(evt, pageId) { document.querySelectorAll('.page').forEach(p => p.classList.remove('active-page')); document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active')); document.getElementById(pageId).classList.add('active-page'); evt.currentTarget.classList.add('active'); }
    function createObjectList(containerId, dataObject, emptyText = "空空如也") { const container = document.getElementById(containerId); if (!container) return; container.innerHTML = ''; const entries = Object.entries(dataObject || {}).filter(([key]) => key !== '$meta' && key.toLowerCase() !== '无'); if (entries.length > 0) { entries.forEach(([name, description]) => { const itemDiv = document.createElement('div'); itemDiv.className = 'list-item'; const descText = Array.isArray(description) ? description[0] : description; itemDiv.innerHTML = `<div class="item-name">${name}</div><div class="item-desc">${descText}</div>`; container.appendChild(itemDiv); }); } else { container.innerHTML = `<div class="list-empty">${emptyText}</div>`; } }

    function updateStatusPanel(gameData) { 
        if (!gameData || (!gameData.stat_data && !gameData.display_data)) { document.body.innerHTML = "<p style='color:red;'>数据错误：缺少 stat_data 或 display_data</p>"; return; } 
        const stat_data = gameData.stat_data || {};
        const display_data = gameData.display_data || stat_data;
        const hp_cur = SafeGetValue(stat_data, '埃莉西娅.派生属性.生命值.当前值', 0);
        const hp_max = SafeGetValue(stat_data, '埃莉西娅.派生属性.生命值.最大值', 100);
        updateProgressBar('hp-bar', 'hp-value', hp_cur, hp_max);
        const mp_cur = SafeGetValue(stat_data, '埃莉西娅.派生属性.魔力值.当前值', 0);
        const mp_max = SafeGetValue(stat_data, '埃莉西娅.派生属性.魔力值.最大值', 100);
        updateProgressBar('mp-bar', 'mp-value', mp_cur, mp_max);
        const sta_cur = SafeGetValue(stat_data, '埃莉西娅.派生属性.精力.当前值', 0);
        const sta_max = SafeGetValue(stat_data, '埃莉西娅.派生属性.精力.最大值', 100);
        updateProgressBar('sta-bar', 'sta-value', sta_cur, sta_max);
        const aro_cur = SafeGetValue(stat_data, '埃莉西娅.核心状态.快感值', 0);
        updateProgressBar('arousal-bar', 'arousal-value', aro_cur, 100);

        setText('world-date', SafeGetValue(display_data, '世界.日期'));
        setText('world-time', SafeGetValue(display_data, '世界.时间'));
        setText('world-location', SafeGetValue(display_data, '世界.地点'));
