        @keyframes gradient-flow { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }
        @keyframes rise-and-sway { 0% { background-position: 10% 100%; } 25% { background-position: 0% 75%; } 50% { background-position: 15% 50%; } 75% { background-position: 5% 25%; } 100% { background-position: 10% 0%; } }
        @keyframes rise-and-drift { 0% { background-position: 80% 100%; } 20% { background-position: 90% 80%; } 40% { background-position: 75% 60%; } 60% { background-position: 85% 40%; } 80% { background-position: 70% 20%; } 100% { background-position: 80% 0%; } }
